export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  const { ball } = state;
  let bouncedX = false;
  let bouncedY = false;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    let hit = collides(ball, brick);
    if (!hit && ball.prevX !== undefined) {
      const minX = Math.min(ball.prevX, ball.x) - ball.r;
      const maxX = Math.max(ball.prevX, ball.x) + ball.r;
      const minY = Math.min(ball.prevY, ball.y) - ball.r;
      const maxY = Math.max(ball.prevY, ball.y) + ball.r;
      if (maxX > brick.x && minX < brick.x + brick.w && maxY > brick.y && minY < brick.y + brick.h) {
        hit = true;
      }
    }

    if (hit) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      const dxL = (ball.x + ball.r) - brick.x;
      const dxR = (brick.x + brick.w) - (ball.x - ball.r);
      const dyT = (ball.y + ball.r) - brick.y;
      const dyB = (brick.y + brick.h) - (ball.y - ball.r);

      const minXPen = Math.min(dxL, dxR);
      const minYPen = Math.min(dyT, dyB);

      if (minXPen < minYPen) {
        // Side hit
        if (!bouncedX) {
          ball.vx = (dxL < dxR) ? -Math.abs(ball.vx) : Math.abs(ball.vx);
          ball.x = (dxL < dxR) ? brick.x - ball.r : brick.x + brick.w + ball.r;
          bouncedX = true;
        }
      } else if (minYPen < minXPen) {
        // Top/Bottom hit
        if (!bouncedY) {
          ball.vy = (dyT < dyB) ? -Math.abs(ball.vy) : Math.abs(ball.vy);
          ball.y = (dyT < dyB) ? brick.y - ball.r : brick.y + brick.h + ball.r;
          bouncedY = true;
        }
      } else {
        // Corner hit: flip both
        if (!bouncedX) {
          ball.vx = (dxL < dxR) ? -Math.abs(ball.vx) : Math.abs(ball.vx);
          ball.x = (dxL < dxR) ? brick.x - ball.r : brick.x + brick.w + ball.r;
          bouncedX = true;
        }
        if (!bouncedY) {
          ball.vy = (dyT < dyB) ? -Math.abs(ball.vy) : Math.abs(ball.vy);
          ball.y = (dyT < dyB) ? brick.y - ball.r : brick.y + brick.h + ball.r;
          bouncedY = true;
        }
      }
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

